    62		cond, err := buildCondition(parsed.GetExpr(), parseContext{schema: e.schema, now: e.nowFunc()})
    63		if err != nil {
    64			return nil, err
    65		}
    66	
    67		return &Program{
    68			schema:    e.schema,
    69			condition: cond,
    70		}, nil
    71	}
